# проверка: во всех языках одни и те же подстановки {n}
for k, v in T.items():
    ph = lambda t: sorted(set(re.findall(r"\{\d+\}", t)))
    assert ph(k) == ph(v[0]) == ph(v[1]), ("подстановки не совпадают", k)
out = {k: {"en": v[0], "ce": v[1]} for k, v in T.items()}
